@Entity
public class Member {

    @Id @GeneratedValue
    @Column(name = "MEMBER_ID")
    private Long id;

    private String name;
    private String city;
    private String street;
    private String zipcode;

    protected Member() {}
    // getter / setter 생략
}

@Entity
@Table(name = "ORDERS")          // ← ORDER 는 예약어다
public class Order {

    @Id @GeneratedValue
    @Column(name = "ORDER_ID")
    private Long id;

    @Column(name = "MEMBER_ID")
    private Long memberId;       // ← 참조가 아니라 그냥 값(FK)

    private LocalDateTime orderDate;

    @Enumerated(EnumType.STRING)  // 5.3절 — ORDINAL 절대 금지
    private OrderStatus status;

    protected Order() {}
}

@Entity
public class OrderItem {

    @Id @GeneratedValue
    @Column(name = "ORDER_ITEM_ID")
    private Long id;

    @Column(name = "ORDER_ID")
    private Long orderId;        // ← FK 값

    @Column(name = "ITEM_ID")
    private Long itemId;         // ← FK 값

    private int orderPrice;      // 주문 당시의 가격
    private int count;

    protected OrderItem() {}
}

@Entity
public class Item {

    @Id @GeneratedValue
    @Column(name = "ITEM_ID")
    private Long id;

    private String name;
    private int price;
    private int stockQuantity;

    protected Item() {}
}

